  ('g6', 'https://gdkqlzggyhzznomnmsvr.supabase.co/storage/v1/object/public/kansari-uploads/hospitality-moment.jpg', 'Hospitality & Details', 'আন্তরিক সেবা ও যত্নশীল আতিথেয়তা', 'square', 6, false),
  ('g7', 'https://gdkqlzggyhzznomnmsvr.supabase.co/storage/v1/object/public/kansari-uploads/grand-kansari-thali.jpg', 'The Grand Kansari Thali', 'ঐতিহ্যবাহী কাঁসার পাত্রে পরিবেশন', 'square', 4, true)
insert into reviews (id, name, text, date, rating, published, created_at) values
  ('r1', 'তাহসান রহমান (Tahsan Rahman)', 'কাচ্চি বিরিয়ানির মাংস এত তুলতুলে আর চালের সুবাস চমৎকার! ঢাকার ভেতরে খাঁটি বাংলাদেশি ঐতিহ্যবাহী খাবারের জন্য কাঁসারী অনন্য।', 'অক্টোবর ২০২৫', 5, true, now() - interval '20 days'),
  ('r2', 'নুসরাত জাহান (Nusrat Jahan)', 'কালাভুনা এবং সরিষা ইলিশ অসাধারণ লেগেছে। কাঁসার পাত্রে গরম গরম পরিবেশন আর পারিবারিক পরিবেশ মন কেড়ে নেওয়ার মতো।', 'সেপ্টেম্বর ২০২৫', 5, true, now() - interval '15 days'),
  ('r3', 'ইফতেখার আহমেদ (Iftekhar Ahmed)', 'পরিপাটি ও রুচিশীল ডাইনিং। প্রতিটি পদে খাঁটি স্বাদ ধরে রাখা হয়েছে। বিশেষ করে বিয়ের বাড়ির মোরগ পোলাও আর বোরহানি ছিল দারুণ।', 'নভেম্বর ২০২৫', 5, true, now() - interval '10 days'),
  ('r4', 'সাবরিনা চৌধুরী (Sabrina Chowdhury)', 'বগুড়ার দই আর জাফরানি ফিরনি দিয়ে ভোজ শেষ করার অনুভূতি ছিল অতুলনীয়। কর্মীদের ব্যবহারও অত্যন্ত আন্তরিক ও অমায়িক।', 'ডিসেম্বর ২০২৫', 5, true, now() - interval '5 days')
insert into settings (id, data) values
  ('main', '{"name": "KANSARI", "bengaliName": "কাঁসারী", "tagline": "স্বাদের শিকড়। নতুন এক আয়োজন।", "englishTagline": "Authentic Bangali flavours, thoughtfully crafted.", "description": "মাটির কাছাকাছি খাঁটি বাংলাদেশি স্বাদ, আধুনিক পরিপাটি পরিবেশে—ঢাকার হৃদয়ে এক নতুন খাবারের অভিজ্ঞতা।", "englishDescription": "At Kansari, time-honoured Bangladeshi culinary traditions meet contemporary culinary finesse. Celebrating genuine heritage recipes in Dhaka.", "location": "Mohammadpur, Dhaka", "address": "House 14, Road 4, Ring Road\nMohammadpur, Dhaka 1207, Bangladesh", "phone": "+880 1740 527078", "whatsapp": "+880 1740 527078", "email": "contact@kansari.com", "socials": {"facebook": "https://facebook.com/kansaribd", "instagram": "https://instagram.com/kansari.dhaka"}, "openingHours": [{"day": "Saturday", "bengaliDay": "শনিবার", "isOpen": true, "openTime": "11:30 AM", "closeTime": "11:00 PM"}, {"day": "Sunday", "bengaliDay": "রবিবার", "isOpen": true, "openTime": "11:30 AM", "closeTime": "11:00 PM"}, {"day": "Monday", "bengaliDay": "সোমবার", "isOpen": true, "openTime": "11:30 AM", "closeTime": "11:00 PM"}, {"day": "Tuesday", "bengaliDay": "মঙ্গলবার", "isOpen": true, "openTime": "11:30 AM", "closeTime": "11:00 PM"}, {"day": "Wednesday", "bengaliDay": "বুধবার", "isOpen": true, "openTime": "11:30 AM", "closeTime": "11:00 PM"}, {"day": "Thursday", "bengaliDay": "বৃহস্পতিবার", "isOpen": true, "openTime": "11:30 AM", "closeTime": "11:00 PM"}, {"day": "Friday", "bengaliDay": "শুক্রবার", "isOpen": true, "openTime": "01:30 PM", "closeTime": "11:30 PM", "specialNote": "জুমার নামাজের পর শুরু"}], "content": {"heroHeadline": "An Authentic Bangladeshi Culinary Experience", "heroBengaliHeadline": "স্বাদের শিকড়। নতুন এক আয়োজন।", "heroSupportingText": "Dhaka''s premier destination for time-honoured heritage recipes cooked with pure artisanal spices.", "storyHeadline": "Roots, Fire & Heritage Brass", "storyBengaliHeadline": "কাঁসার পাত্রে ঐতিহ্যের সুবাস", "storyText": "In ancient Bengal, bell metal (কাঁসা) was not just tableware; it was a sacred canvas for hospitality. At Kansari, we revive these sacred culinary traditions.", "finalCtaHeading": "আপনার জন্য কাঁসার থালায় প্রস্তুত আমাদের আয়োজন।"}}'::jsonb)
